from collections import deque
from openpyxl.utils import column_index_from_string
ws = wb.active
# Build color map
cell_color = {}
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell = ws.cell(row=r, column=c)
        rgb = cell.fill.fgColor.rgb[-6:].upper() if cell.fill and cell.fill.fgColor and cell.fill.fgColor.rgb else None
        cell_color[(r,c)] = rgb

# Strict-blue function
def is_blue(rgb):
    if not rgb: return False
    r = int(rgb[0:2],16); g = int(rgb[2:4],16); b = int(rgb[4:6],16)
    return r<=10 and g<=10 and b>=245

start = (1,1)
max_row, max_col = ws.max_row, ws.max_column
DIRECTIONS = {'up':(-2,0),'down':(2,0),'left':(0,-2),'right':(0,2)}
queue = deque([(start[0], start[1], 0, None, [])])
visited=set()
final=None
while queue:
    r,c,m,prev,path = queue.popleft()
    if m==11:
        final=(r,c); break
    for name,(dr,dc) in DIRECTIONS.items():
        if prev and ((prev=='up' and name=='down') or (prev=='down' and name=='up') or (prev=='left' and name=='right') or (prev=='right' and name=='left')):
            continue
        nr, nc = r+dr, c+dc
        if 1<=nr<=max_row and 1<=nc<=max_col:
            if not is_blue(cell_color[(nr,nc)]):
                state=(nr,nc,m+1,name)
                if state not in visited:
                    visited.add(state)
                    queue.append((nr,nc,m+1,name,path+[(nr,nc)]))
if final:
    print('Final after 11 moves:', final, 'Color:', cell_color[final])
else:
    print('No valid path up to 11 moves')
